/**
 * Direct provider for chatgpt.com — same surface as the DeepSeek provider
 * (`createSession`, `completion`, `chat`) but transport is Playwright,
 * because chatgpt.com sits behind Cloudflare + a sentinel anti-bot stack
 * that defeats raw Node fetch. See ./transport.ts for the rationale.
 *
 * Sequence per turn:
 *   1. (first turn only) `requireSession()` — confirms we're signed in.
 *   2. POST /backend-api/sentinel/chat-requirements
 *        → returns { token } (and optional proofofwork/arkose/turnstile
 *          challenges). When the request happens through the real page,
 *          the page's own JS solves PoW/turnstile transparently — we just
 *          consume the resulting `token`.
 *   3. POST /backend-api/conversation
 *        Headers: openai-sentinel-chat-requirements-token: <token>
 *        Body:    { action: "next", messages: [user-msg], conversation_id,
 *                   parent_message_id, model, ... }
 *        Response: SSE — newer wire is JSON-Patch shaped
 *                  ({"v": initial}, {"v": "delta"}, {"p": ..., "o": ...}).
 *
 * Session model:
 *   ChatGPT doesn't pre-create conversation ids; the first /conversation
 *   call with conversation_id=null creates one and returns it. Our
 *   `createSession()` mirrors the DeepSeek shape by returning a synthetic
 *   id that maps to "no conversation yet"; the real conversation_id is
 *   captured from the first completion and threaded through `parentMessageId`.
 *
 *   To make this transparent, `chat()` accepts both a `sessionId` (for
 *   API symmetry with DeepSeek) and tracks the real (conversation_id,
 *   parent_message_id) pair internally inside the `ChatResult` so the
 *   caller can pass them back in the next call.
 */

import { randomUUID } from "node:crypto";
import {
  apiJson,
  ChatGPTAuthError,
  ChatGPTTransportError,
  requireSession,
  streamApi,
} from "./transport.js";

// ── Errors ────────────────────────────────────────────────────────────────
export class ChatGPTError extends Error {
  constructor(msg: string, public readonly cause?: unknown) {
    super(msg);
    this.name = "ChatGPTError";
  }
}
export class ChatGPTRateLimitError extends ChatGPTError {
  constructor(m: string, c?: unknown) { super(m, c); this.name = "ChatGPTRateLimitError"; }
}
export class ChatGPTAbortedError extends ChatGPTError {
  constructor(m = "aborted") { super(m); this.name = "ChatGPTAbortedError"; }
}
export class ChatGPTProtocolError extends ChatGPTError {
  constructor(m: string, c?: unknown) { super(m, c); this.name = "ChatGPTProtocolError"; }
}
// Re-export transport errors so callers only need one import.
export { ChatGPTAuthError, ChatGPTTransportError } from "./transport.js";

// ── Session ───────────────────────────────────────────────────────────────
export interface SessionHandle {
  /** Synthetic id (UUID v4). Real conversation_id is created on first turn. */
  sessionId: string;
  /** Identity captured during verification — for logging. */
  user: { id: string; email?: string; name?: string };
}

export async function createSession(): Promise<SessionHandle> {
  const s = await requireSession();
  return { sessionId: randomUUID(), user: s.user };
}

// ── Sentinel ──────────────────────────────────────────────────────────────
interface SentinelResponse {
  token: string;
  proofofwork?: { required: boolean; seed: string; difficulty: string };
  arkose?:      { required: boolean; dx?: string | null };
  turnstile?:   { required: boolean; dx?: string | null };
  persona?: string;
}

async function fetchSentinelToken(): Promise<string> {
  // Empty body { p: "" } is what the live web client sends on the first call
  // of a fresh conversation. The page's own JS hooks into this request and
  // injects PoW/Arkose/Turnstile artifacts before/after as needed — when we
  // hop through page.evaluate we inherit that behavior for free.
  const body = await apiJson<SentinelResponse>("/backend-api/sentinel/chat-requirements", {
    method: "POST",
    body: { p: "" },
  });
  if (!body.token) {
    throw new ChatGPTProtocolError(
      "sentinel returned no token — page JS may have failed PoW/Arkose. " +
      "Re-run with chatgpt:setup --headed to refresh the session.",
    );
  }
  if (body.arkose?.required) {
    // We don't (yet) have an automatic Arkose solver. Note for the user
    // and bail with a clear message.
    throw new ChatGPTAuthError(
      "Arkose challenge required by sentinel — open chatgpt.com in the persistent " +
      "profile, solve it manually once, then retry.",
    );
  }
  return body.token;
}

// ── SSE parser ────────────────────────────────────────────────────────────
// ChatGPT's wire is JSON-Patch shaped (similar in spirit to DeepSeek's):
//
//   First event  : data: { "v": { "message": {...full initial}, "conversation_id": "..." }, "c": <seq> }
//                  → extract conversation_id and message.id; seed text from
//                    message.content.parts[0] (usually "").
//   Append delta : data: { "v": "more text" }                            (shorthand — continues prev path)
//                  data: { "p": "/message/content/parts/0", "o": "append", "v": "txt" }
//   Status patch : data: { "p": "/message/status", "o": "replace", "v": "finished_successfully" }
//                  data: { "p": "/message/end_turn", "o": "replace", "v": true }
//   Batch        : data: { "p": "", "o": "patch", "v": [{p,o,v}, ...] }
//   Terminal     : data: [DONE]
//
// We only need: the streamed text, the conversation_id, the assistant
// message_id (for parent_message_id on the next turn), and a finish_reason
// derived from `/message/status` or end_turn.

export interface SseParserCallbacks {
  onChunk?: (text: string) => void;
}

export interface SseParserState {
  text: string;
  conversationId: string | null;
  /** id of the assistant message — needed as parent_message_id on next turn. */
  assistantMessageId: string | null;
  finishReason: string | null;
  done: boolean;
}

export function createSseParser(cb: SseParserCallbacks = {}): {
  feed: (s: string) => void;
  state: SseParserState;
} {
  const state: SseParserState = {
    text: "", conversationId: null, assistantMessageId: null,
    finishReason: null, done: false,
  };
  let buf = "";
  // The current "anchor" path the shorthand `{"v": "..."}` appends to.
  // Default per the wire spec is the first text part of the assistant message.
  let lastPath = "/message/content/parts/0";

  function appendText(s: string): void {
    if (!s) return;
    state.text += s;
    cb.onChunk?.(s);
  }

  function applyPatch(p: string | undefined, op: string | undefined, v: unknown): void {
    if (!p) return;
    if (op === "append" && p === "/message/content/parts/0" && typeof v === "string") {
      appendText(v);
      lastPath = p;
      return;
    }
    if (op === "replace" && p === "/message/status" && typeof v === "string") {
      // "finished_successfully" | "in_progress" | "finished_partial" | ...
      if (v === "finished_successfully") state.finishReason = "stop";
      else if (v.startsWith("finished_")) state.finishReason = v;
      return;
    }
    if (op === "replace" && p === "/message/end_turn" && v === true) {
      state.finishReason = state.finishReason ?? "stop";
      return;
    }
    // Unknown patches are intentionally ignored.
  }

  function handleEnvelope(obj: Record<string, unknown>): void {
    // Bridge-side error injection from streamApi (non-2xx body capture).
    if (typeof obj.error === "string") return;

    // First-message snapshot.
    if (!("p" in obj) && obj.v && typeof obj.v === "object") {
      const root = obj.v as Record<string, unknown>;
      const conv = root.conversation_id;
      if (typeof conv === "string") state.conversationId = conv;
      const msg = root.message as Record<string, unknown> | undefined;
      if (msg) {
        if (typeof msg.id === "string") state.assistantMessageId = msg.id;
        const content = msg.content as Record<string, unknown> | undefined;
        const parts = content?.parts as unknown[] | undefined;
        if (Array.isArray(parts) && typeof parts[0] === "string") {
          appendText(parts[0]);
        }
      }
      lastPath = "/message/content/parts/0";
      return;
    }

    // Batch patch: {"p":"","o":"patch","v":[{p,o,v}, ...]}
    if (obj.o === "patch" && Array.isArray(obj.v)) {
      for (const sub of obj.v as Array<Record<string, unknown>>) {
        if (sub && typeof sub === "object") {
          applyPatch(
            typeof sub.p === "string" ? sub.p : undefined,
            typeof sub.o === "string" ? sub.o : undefined,
            sub.v,
          );
        }
      }
      return;
    }

    // Full patch.
    if (typeof obj.p === "string") {
      applyPatch(obj.p, typeof obj.o === "string" ? obj.o : "append", obj.v);
      return;
    }

    // Shorthand continuation — `{"v": "text"}` with no `p` → append to last path.
    if (!("p" in obj) && typeof obj.v === "string") {
      if (lastPath === "/message/content/parts/0") appendText(obj.v);
      return;
    }
  }

  function feed(s: string): void {
    if (state.done) return;
    buf += s;
    let nl: number;
    while ((nl = buf.indexOf("\n\n")) >= 0) {
      const ev = buf.slice(0, nl);
      buf = buf.slice(nl + 2);
      for (const line of ev.split("\n")) {
        if (!line.startsWith("data: ")) continue;
        const data = line.slice(6);
        if (data === "[DONE]") {
          state.done = true;
          state.finishReason = state.finishReason ?? "stop";
          return;
        }
        // The bridge marks transport-level HTTP errors with a sentinel
        // string so we can surface them with the right error class.
        if (data.startsWith("__HTTP_ERROR__:")) {
          const rest = data.slice("__HTTP_ERROR__:".length);
          const colon = rest.indexOf(":");
          const status = Number(rest.slice(0, colon));
          const body = rest.slice(colon + 1);
          throw classifyHttp(status, body);
        }
        let j: unknown;
        try { j = JSON.parse(data); } catch { continue; }
        if (j && typeof j === "object") handleEnvelope(j as Record<string, unknown>);
      }
    }
  }

  return { feed, state };
}

function classifyHttp(status: number, body: string): ChatGPTError {
  if (status === 401 || status === 403) return new ChatGPTAuthError(`conversation → ${status}: ${body.slice(0, 200)}`);
  if (status === 429) return new ChatGPTRateLimitError(`conversation → 429: ${body.slice(0, 200)}`);
  return new ChatGPTError(`conversation → HTTP ${status}: ${body.slice(0, 200)}`);
}

// ── Completion (single turn) ──────────────────────────────────────────────
export interface CompletionOpts {
  /** Required only for symmetry with DeepSeek — not sent on the wire. */
  sessionId?: string;
  prompt: string;
  /** From a previous turn (conversation_id + assistantMessageId). Pass both
   *  or neither — the first turn starts a new conversation. */
  conversationId?: string | null;
  parentMessageId?: string | null;
  /** Model slug. Defaults to "auto" which lets the server pick (matches the
   *  default the webapp uses for free users). Examples: "gpt-5", "gpt-5-mini",
   *  "auto". */
  model?: string;
  onChunk?: (text: string) => void;
  signal?: AbortSignal;
  timeoutMs?: number;
}

export interface CompletionResult {
  text: string;
  conversationId: string | null;
  assistantMessageId: string | null;
  finishReason: string | null;
  latencyMs: number;
  truncated: boolean;
}

export async function completion(opts: CompletionOpts): Promise<CompletionResult> {
  const t0 = Date.now();
  if (opts.signal?.aborted) throw new ChatGPTAbortedError();

  const sentinelToken = await fetchSentinelToken();

  const messageId = randomUUID();
  const requestId = randomUUID();
  const parentId  = opts.parentMessageId ?? randomUUID();

  const body = {
    action: "next",
    messages: [
      {
        id: messageId,
        author: { role: "user" },
        content: { content_type: "text", parts: [opts.prompt] },
        metadata: {},
      },
    ],
    conversation_id: opts.conversationId ?? null,
    parent_message_id: parentId,
    model: opts.model ?? "auto",
    timezone_offset_min: -180,
    history_and_training_disabled: false,
    conversation_mode: { kind: "primary_assistant" },
    websocket_request_id: requestId,
    supported_encodings: ["v1"],
    client_contextual_info: {
      is_dark_mode: false,
      time_since_loaded: 60,
      page_height: 768,
      page_width: 1366,
      pixel_ratio: 1,
      screen_height: 768,
      screen_width: 1366,
    },
  };

  const parser = createSseParser({ onChunk: opts.onChunk });
  // Per-call error capture for parser callbacks (parser feed can throw on
  // HTTP errors injected by the transport bridge). Closed over by the
  // onChunk callback so concurrent completions don't race.
  let streamError: unknown = null;

  const ctrl = new AbortController();
  const outerSignal = opts.signal;
  const onOuterAbort = (): void => ctrl.abort();
  if (outerSignal) {
    if (outerSignal.aborted) throw new ChatGPTAbortedError();
    outerSignal.addEventListener("abort", onOuterAbort, { once: true });
  }
  const timeoutMs = opts.timeoutMs ?? 180_000;
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);

  try {
    await streamApi("/backend-api/conversation", {
      method: "POST",
      headers: {
        "openai-sentinel-chat-requirements-token": sentinelToken,
        "oai-language": "en-US",
      },
      body,
      signal: ctrl.signal,
      onChunk: (chunk) => {
        try { parser.feed(chunk); } catch (e) {
          ctrl.abort();
          streamError = e;
        }
      },
    });
  } catch (e) {
    if (e instanceof ChatGPTTransportError) throw e;
    throw new ChatGPTError(`completion failed: ${(e as Error).message}`, e);
  } finally {
    clearTimeout(timer);
    if (outerSignal) outerSignal.removeEventListener("abort", onOuterAbort);
  }

  if (streamError) throw streamError;
  if (ctrl.signal.aborted && opts.signal?.aborted) throw new ChatGPTAbortedError();

  return {
    text: parser.state.text,
    conversationId: parser.state.conversationId,
    assistantMessageId: parser.state.assistantMessageId,
    finishReason: parser.state.finishReason,
    latencyMs: Date.now() - t0,
    truncated: parser.state.finishReason !== "stop" || !parser.state.done,
  };
}

// ── chat(): auto-continue across truncations ──────────────────────────────
const DEFAULT_CONTINUE_PROMPT_AR =
  "تابع من النقطة التي توقفت عندها بالضبط، حرفياً. لا تكرر ما كتبت سابقاً. لا تبدأ من جديد. لا تلخص. أكمل الكتابة من الكلمة التالية مباشرة كأنك لم تتوقف.";

export interface ChatOpts extends Omit<CompletionOpts, "onChunk"> {
  autoContinue?: boolean;
  maxContinuations?: number;
  continuePrompt?: string;
  onChunk?: (text: string) => void;
  onContinuation?: (n: number, reason: string) => void;
}

export interface ChatResult {
  text: string;
  conversationId: string | null;
  finalMessageId: string | null;
  finishReason: string;
  continuations: number;
  totalLatencyMs: number;
  turns: Array<{ turn: number; chars: number; latencyMs: number; finishReason: string | null; truncated: boolean }>;
}

export async function chat(opts: ChatOpts): Promise<ChatResult> {
  const t0 = Date.now();
  const max = opts.maxContinuations ?? 4;
  const autoContinue = opts.autoContinue ?? true;
  const continuePrompt = opts.continuePrompt ?? DEFAULT_CONTINUE_PROMPT_AR;

  let conversationId: string | null = opts.conversationId ?? null;
  let parentMessageId: string | null = opts.parentMessageId ?? null;
  let totalText = "";
  const turns: ChatResult["turns"] = [];
  let prevTail = "";

  for (let turn = 0; turn <= max; turn++) {
    if (opts.signal?.aborted) throw new ChatGPTAbortedError();

    const prompt = turn === 0 ? opts.prompt : continuePrompt;
    if (turn > 0) {
      const prev = turns[turn - 1];
      const reason = prev?.finishReason ?? (prev?.truncated ? "truncated" : "unknown");
      opts.onContinuation?.(turn, reason);
    }

    const result = await completion({
      sessionId: opts.sessionId,
      prompt,
      conversationId,
      parentMessageId,
      model: opts.model,
      signal: opts.signal,
      timeoutMs: opts.timeoutMs,
      onChunk: opts.onChunk,
    });

    totalText += result.text;
    conversationId = result.conversationId ?? conversationId;
    parentMessageId = result.assistantMessageId ?? parentMessageId;
    turns.push({
      turn, chars: result.text.length, latencyMs: result.latencyMs,
      finishReason: result.finishReason, truncated: result.truncated,
    });

    if (!result.truncated) {
      return { text: totalText, conversationId, finalMessageId: parentMessageId,
               finishReason: "stop", continuations: turn,
               totalLatencyMs: Date.now() - t0, turns };
    }
    if (!autoContinue) {
      return { text: totalText, conversationId, finalMessageId: parentMessageId,
               finishReason: result.finishReason ?? "truncated", continuations: turn,
               totalLatencyMs: Date.now() - t0, turns };
    }

    const tail = result.text.slice(-200);
    if (turn > 0 && prevTail && tailsOverlap(prevTail, tail)) {
      return { text: totalText, conversationId, finalMessageId: parentMessageId,
               finishReason: "stalled", continuations: turn,
               totalLatencyMs: Date.now() - t0, turns };
    }
    prevTail = tail;
  }

  return {
    text: totalText, conversationId, finalMessageId: parentMessageId,
    finishReason: "max_continuations", continuations: max,
    totalLatencyMs: Date.now() - t0, turns,
  };
}

function tailsOverlap(a: string, b: string): boolean {
  if (a.length < 50 || b.length < 50) return false;
  const shorter = a.length < b.length ? a : b;
  const longer  = a.length < b.length ? b : a;
  const sample  = shorter.slice(0, Math.floor(shorter.length * 0.9));
  return longer.includes(sample);
}

// ── Re-exports ────────────────────────────────────────────────────────────
export { close, getSession, requireSession } from "./transport.js";
